export function normalizeD1RecordName(name: string): string {
  return String(name || '')
    .toLowerCase()
    .replace(/['`']/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

export function lookupD1RecordCatalog(name: string): D1RecordCatalogEntry | null {
  return D1_RECORDS_BY_NAME[normalizeD1RecordName(name)] || null;
}

